"""
Event Payload Types — shared between engine.py and scheduler
=============================================================
Kept in a separate module so engine.py and train_scheduler.py can both
import from here without creating circular imports.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ArrivePayload:
    """Payload for TRAIN_ARRIVE events generated by the depart handler."""
    train_id:    str
    at_station:  str
    section_id:  str
    is_terminus: bool


@dataclass(frozen=True)
class HoldPayload:
    """Payload for TRAIN_HOLD events."""
    train_id:   str
    at_station: str
    reason:     str


@dataclass(frozen=True)
class ReleasePayload:
    """Payload for TRAIN_RELEASE events."""
    train_id:   str
    at_station: str


@dataclass(frozen=True)
class LoopPayload:
    """Payload for TRAIN_ENTER_LOOP and TRAIN_EXIT_LOOP events."""
    train_id:   str
    at_station: str
    loop_id:    str
